import unittest
from solution import token_counts

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(token_counts("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(token_counts("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(token_counts(""), {})
    def test_whitespace(self):
        self.assertEqual(token_counts("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(token_counts("solo"), {"solo": 1})
